<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Client\Infrastructure\Driver\Rest;

use DateTimeImmutable;
use DateTimeInterface;
use InvalidArgumentException;
use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Infrastructure\Sql\SqlTemplate;
use Civi\Lughauth\Features\OAuth\Client\Application\Usecase\IssueInitialAccessToken\IssueInitialAccessTokenCaller;
use Civi\Lughauth\Features\OAuth\Client\Application\Usecase\IssueInitialAccessToken\IssueInitialAccessTokenParams;
use Civi\Lughauth\Features\OAuth\Client\Application\Usecase\IssueInitialAccessToken\IssueInitialAccessTokenUsecase;

/**
 * Administration endpoint that issues a DCR initial access token (task 023) and returns it in
 * clear, the only time it is available: the generated CRUD of dcr-initial-access-token keeps
 * listing and revoking the tokens, but only stores digests.
 *
 * Only an admin may issue: a tenant admin always for their own tenant (naming another one is
 * refused), root for the tenant named in the body, which is then required.
 */
class InitialAccessTokenIssueController
{
    /** Lifetime of a token issued without expiresAt. */
    private const string DEFAULT_TTL = '+1 day';

    public function __construct(
        private readonly Context $context,
        private readonly SqlTemplate $sql,
        private readonly IssueInitialAccessTokenUsecase $usecase,
    ) {
    }

    #[OA\Post(
        path: '/api/access/dcr-initial-access-tokens/~/issue',
        summary: 'Issue a DCR initial access token',
        description: 'Generates an initial access token for dynamic client registration (RFC 7591) and returns it once.',
        tags: ['Dcr initial access token'],
        requestBody: new OA\RequestBody(content: new OA\JsonContent(properties: [
            new OA\Property(property: 'tenant', type: 'object', description: 'Only for root: {"$ref": tenant uid}'),
            new OA\Property(property: 'description', type: 'string'),
            new OA\Property(property: 'expiresAt', type: 'string', format: 'date-time', description: 'Defaults to one day'),
            new OA\Property(property: 'maxUses', type: 'integer', default: 1),
            new OA\Property(property: 'allowedGrantTypes', type: 'array', items: new OA\Items(type: 'string')),
        ])),
        responses: [
            new OA\Response(response: 201, description: 'Issued; the token is shown only in this response'),
            new OA\Response(response: 400, description: 'Invalid request (also an unknown tenant, or root without tenant)'),
            new OA\Response(response: 401, description: 'Not an admin, or a tenant admin naming another tenant'),
        ]
    )]
    public function issue(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        try {
            $params = $this->readParams((array) ($request->getParsedBody() ?? []));
        } catch (InvalidArgumentException $ex) {
            return $this->json($response->withStatus(400), ['error' => 'invalid_request', 'error_description' => $ex->getMessage()]);
        }
        $this->sql->begin();
        try {
            $result = $this->usecase->issue($params);
            $this->sql->commit();
        } catch (InvalidArgumentException $ex) {
            return $this->json($response->withStatus(400), ['error' => 'invalid_request', 'error_description' => $ex->getMessage()]);
        } finally {
            $this->sql->close();
        }
        return $this->json($response->withStatus(201)->withHeader('Cache-Control', 'no-store'), [
            'uid' => $result->uid,
            'token' => $result->token,
            'expiresAt' => $result->expiresAt->format(DateTimeInterface::ATOM),
            'maxUses' => $result->maxUses,
            'allowedGrantTypes' => $result->allowedGrantTypes,
        ]);
    }

    private function readParams(array $body): IssueInitialAccessTokenParams
    {
        $tenant = $body['tenant']['$ref'] ?? null;
        $grantTypes = $body['allowedGrantTypes'] ?? null;
        if ($grantTypes !== null && (!is_array($grantTypes) || array_filter($grantTypes, static fn (mixed $g): bool => !is_string($g) || $g === '') !== [])) {
            throw new InvalidArgumentException('allowedGrantTypes must be a list of grant types');
        }
        try {
            $expiresAt = new DateTimeImmutable(is_string($body['expiresAt'] ?? null) ? $body['expiresAt'] : self::DEFAULT_TTL);
        } catch (\Exception) {
            throw new InvalidArgumentException('expiresAt must be a date-time');
        }
        $identity = $this->context->getIdentity();
        return new IssueInitialAccessTokenParams(
            caller: new IssueInitialAccessTokenCaller(
                tenantUid: $identity->getTenant(),
                admin: $identity->hasRole('admin'),
                globalAccess: $identity->hasScope('platform:global_access'),
            ),
            tenantUid: is_string($tenant) && $tenant !== '' ? $tenant : null,
            expiresAt: $expiresAt,
            maxUses: is_numeric($body['maxUses'] ?? null) ? (int) $body['maxUses'] : 1,
            allowedGrantTypes: $grantTypes === null ? null : array_values($grantTypes),
            description: is_string($body['description'] ?? null) ? $body['description'] : null,
        );
    }

    private function json(ResponseInterface $response, array $payload): ResponseInterface
    {
        $encoded = json_encode($payload);
        $response->getBody()->write($encoded !== false ? $encoded : '{}');
        return $response->withHeader('Content-Type', 'application/json');
    }
}
